import csv
from decimal import Decimal


def totals(csv_text: str) -> dict[str, Decimal]:
    """Aggregate CSV amounts by name, according to TASK.md."""
    result: dict[str, Decimal] = {}

    if not csv_text.strip():
        return result

    try:
        reader = csv.reader(csv_text.splitlines(True))
        for row in reader:
            # Skip rows that don't have exactly 2 fields
            if len(row) != 2:
                continue

            name, amount_str = row

            # Strip whitespace from name and amount
            name = name.strip()
            amount_str = amount_str.strip()

            # Skip if name is empty
            if not name:
                continue

            # Skip if amount is empty
            if not amount_str:
                continue

            # Validate amount format: optional +/- sign, then one or more ASCII digits,
            # optionally followed by decimal point and one or more ASCII digits
            # Must start with optional sign followed by at least one ASCII digit
            if not (amount_str[0] == '+' or amount_str[0] == '-' or amount_str[0].isdigit()):
                continue

            # Check for decimal point
            if '.' in amount_str:
                parts = amount_str.split('.')
                if len(parts) != 2:
                    continue
                int_part, frac_part = parts

                # Both parts must have at least one ASCII digit
                if not int_part or not frac_part:
                    continue

                # Both parts must be ASCII digits only
                if not int_part.isascii() or not frac_part.isascii():
                    continue
                if not int_part.isdigit() or not frac_part.isdigit():
                    continue
            else:
                # No decimal point - must be all ASCII digits (no sign here)
                if not amount_str.isascii():
                    continue
                if not amount_str.isdigit():
                    continue

            # Valid amount - parse and accumulate
            amount = Decimal(amount_str)

            if name not in result:
                result[name] = Decimal(0)
            result[name] += amount

    except Exception:
        return result

    return result
